{
  "subtype": "predictive_feature_engineering",
  "focus_variable": "label_pos",
  "per_column": [
    {
      "name": "script_quality_verdict",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Reviewer's assessment of the script (poor/good/mixed) is a distinct content dimension that plausibly correlates with overall satisfaction without deterministically restating the binary label."
    },
    {
      "name": "acting_quality_verdict",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Judgment about acting is a separable quality facet that carries predictive signal about positive/negative sentiment while remaining outside the focus variable."
    },
    {
      "name": "production_quality_verdict",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Production/technical quality is another independent aspect of the review that can inform, but does not define, overall label."
    },
    {
      "name": "plot_coherence",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Coherence of the plot is a specific content attribute plausibly linked to satisfaction and not a mechanical restatement of the label."
    },
    {
      "name": "reviewer_emotional_tone",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Sentiment polarity (strongly_negative ... strongly_positive) is essentially a near-restatement of label_pos; the positive/negative label is largely a deterministic read-off of the reviewer's overall tone, so it leaks the outcome rather than predicting it."
    },
    {
      "name": "comparative_benchmark",
      "role": "predictor",
      "is_predictor": true,
      "rationale": "Whether the review compares the film favorably/unfavorably to others is a distinct rhetorical signal that carries predictive information without fully determining the label."
    },
    {
      "name": "rec_signal",
      "role": "leakage",
      "is_predictor": false,
      "rationale": "Explicit recommend/avoid is functionally equivalent to the satisfaction verdict itself; recommending vs. telling readers to avoid maps almost one-to-one onto positive/negative label, so it restates/leaks the focus."
    }
  ],
  "n_predictors": 5,
  "predictive_utility": 0.6,
  "rationale": "The aspect-level verdicts (script, acting, production, plot coherence) and the comparative benchmark are legitimate, non-trivial predictors that decompose the review into distinct quality dimensions each carrying genuine signal beyond raw text. However, reviewer_emotional_tone and rec_signal are near-restatements/leakage of the binary satisfaction label, since polarity and explicit recommend/avoid are essentially the outcome itself. As a set there is real predictive leverage from the aspect features, but the presence of two leaking columns lowers the clean predictive utility."
}

